if (head->data == value) {
    ListNode* toDelete = head;
    head = head->next;
    delete toDelete;
    return true;
}

ListNode* prev = head;
ListNode* curr = head->next;

while (curr != nullptr) {
    if (curr->data == value) {
        prev->next = curr->next;
        delete curr;
        return true;
    }
    prev = curr;
    curr = curr->next;
}

return false;

